# --- Craft plans (AF Buy): N crafts limited by the mats listed, the product's sales, the budget, and the last craft
# still paying. Product 600 posts at 970 (sells 100%, no deposit): 921.5 expected a craft. Mats: 2 x 601 (10 at 1s,
# 10 at 2s, 100 at 5s) + 1 x 602 from a vendor (10c).
X('''MakeItem(600, { med = 1000, med24 = 1000, medAll = 1000, sellThrough = 1, perHour = 2 })
  MakeItem(601, { ladder = { {100, 10}, {200, 10}, {500, 100} }, qty = 120 })
  CEnv = Env({ vendor = { [602] = 10 } })
  CRec = { 7001, 171, 50, 1, { 601, 2, 602, 1 }, 0, 60, 80 }
  CRow = AF_NS.Farm.Craft(600, CRec, CEnv)
  function CPlan(Opts, Row) return AF_NS.Farm.CraftPlan(Row or CRow, Opts, CEnv) end''')
P = L('CPlan({ share = 0.75, hours = 8 })')
ok(P and P.crafts == 10 and P.cost == 3100 and P.profit == 6115 and P.route == 'AH',
   f"N stops where the next craft's mats (2 at 5s + 10c) cost more than it earns: {P and P.crafts} crafts, cost {P and P.cost}, profit {P and P.profit} (want 10, 3100, 6115)")
ok(P and P.mats[1].id == 601 and P.mats[1].qty == 20 and P.mats[1].upTo == 200 and P.mats[1].cost == 3000
   and P.vendorGoods[1].id == 602 and P.vendorGoods[1].qty == 10 and P.vendorGoods[1].cost == 100 and P.vendorCost == 100,
   'plan lists each AH mat (qty, buy up to, cost) and the vendor goods')
X('Items[600].perHour = 0.5')
P = L('CPlan({ share = 0.75, hours = 8 }, AF_NS.Farm.Craft(600, CRec, CEnv))')
ok(P and P.crafts == 3 and P.profit == 2134, f"sales limit: 0.5 sold/h x 75% x 8 h = 3 crafts ({P and P.crafts}, profit {P and P.profit})")
X('Items[600].perHour = 2')
P = L('CPlan({ share = 0.75, hours = 8, cap = 1100 })')
ok(P and P.crafts == 5 and P.cost == 1050, f"budget: 5 crafts cost 10s 50c, 6 would cost 12s 60c (cap 11s): {P and P.crafts}")
X('Items[601].ladder = { {100, 3} }; Items[601].qty = 3')
P = L('CPlan({ share = 0.75, hours = 8 }, AF_NS.Farm.Craft(600, CRec, CEnv))')
ok(P and P.crafts == 1, f"mats listed: 3 units allow 1 craft ({P and P.crafts})")
X('Items[601].ladder = {}; Items[601].qty = 0')
ok(L('CPlan({ share = 0.75, hours = 8 }, AF_NS.Farm.Craft(600, CRec, CEnv))') is None, 'no mats listed: no plan')
X('Items[601].ladder = { {100, 10}, {200, 10}, {500, 100} }; Items[601].qty = 120')
ok(L('(CPlan({ share = 0.75, hours = 8, need = function(c) return c * 10 end }))') is None, "under the profit it needs: no plan")
X('CEnvV = Env({ vendor = { [602] = 10 }, vendorSell = function(id) return id == 600 and 1500 or nil end }); Items[600].perHour = 0.5')
P = L('AF_NS.Farm.CraftPlan(AF_NS.Farm.Craft(600, CRec, CEnvV), { share = 0.75, hours = 8 }, CEnvV)')
ok(P and P.route == 'Vendor' and P.crafts == 60 and P.resell == 1500 and P.profit == 1500 * 60 - 53600,
   f"vendor route: no sales limit, up to the mats listed (each craft still pays at 5s mats): {P and P.crafts} crafts, profit {P and P.profit}")
X('Items[600].perHour = 2')

# Cooldown recipes: only the crafts the cooldown allows in the window (8 h); none when it won't be ready in time.
X("""CRecCd = { 7002, 171, 50, 1, { 601, 2, 602, 1 }, 0, 60, 80, 172800, 0 }
  CRowCd = AF_NS.Farm.Craft(600, CRecCd, CEnv)""")
P = L('CPlan({ share = 0.75, hours = 8 }, CRowCd)')
ok(P and P.crafts == 1 and P.cooldown == 172800, f"48 h cooldown: 1 craft (not 10) ({P and P.crafts})")
r = L('{ AF_NS.Farm.CraftPlan(CRowCd, { share = 0.75, hours = 8, cooldownLeft = function() return 30 * 3600 end }, CEnv) }')
ok(r[1] is None and r[2] == 'cooldown' and r[3] == 30 * 3600, f"on cooldown for 30 h more: no plan, says why ({r[2]}, {r[3]})")
X('CRowCd1 = AF_NS.Farm.Craft(600, { 7003, 171, 50, 1, { 601, 2, 602, 1 }, 0, 60, 80, 3600, 0 }, CEnv)')
P = L('CPlan({ share = 0.75, hours = 8 }, CRowCd1)')
P2 = L('CPlan({ share = 0.75, hours = 8, cooldownLeft = function() return 7.5 * 3600 end }, CRowCd1)')
ok(P and P.crafts == 9 and P2 and P2.crafts == 1, f"1 h cooldown: 9 crafts in 8 h when ready, 1 when ready in 7.5 h ({P and P.crafts}, {P2 and P2.crafts})")
# Selling on the AH: priced at most at what buyers paid (a lone listing far above the sales isn't a price), and the
# product needs hours with sales. Here AF Sell would post at 50s (1c under a lone high listing); buyers paid 10s.
X("""CEnvHi = Env({ vendor = { [602] = 10 }, postPrice = function(I, S) if I.id == 600 then return 5000, 2 end return 970, 2 end })
  CRowHi = AF_NS.Farm.Craft(600, CRec, CEnvHi)""")
P0 = L('AF_NS.Farm.CraftPlan(CRowHi, { share = 0.75, hours = 8 }, CEnvHi)')
P = L('AF_NS.Farm.CraftPlan(CRowHi, { share = 0.75, hours = 8, resaleCap = function(I) return math.min(I.med24, I.medAll) end }, CEnvHi)')
ok(P0 and P0.resell == 5000 and P and P.resell == 1000 and P.capped and P.profit < P0.profit and P.crafts == 10,
   f"resale capped at what buyers paid: 10s, not the 50s listing ({P0 and P0.resell} -> {P and P.resell}, profit {P0 and P0.profit} -> {P and P.profit})")
ok(P and P.sales == L('Items[600].sales') and P.salesHours == L('Items[600].hoursWithSales'), 'the plan carries its evidence (sales, hours with sales)')
X('Items[600].hoursWithSales = 1')
ok(L('(CPlan({ share = 0.75, hours = 8, minSalesHours = 2 }))') is None, 'sold in only 1 hour: not sold on the AH by a craft plan')
X('Items[600].hoursWithSales = nil')
# Flooded products (new listings far outpacing sales) aren't sold on the AH, like flips; the vendor route if it pays.
X("Items[600].status = 'flooded'; CRowFl = AF_NS.Farm.Craft(600, CRec, CEnv)")
r = L("{ AF_NS.Farm.CraftPlan(CRowFl, { share = 0.75, hours = 8, ahStatus = { good = true, slow = true } }, CEnv) }")
ok(r[1] is None and r[2] == 'flooded', f"flooded product: no AH plan, says why ({r[2]})")
P = L("CPlan({ share = 0.75, hours = 8 }, CRowFl)")
ok(P and P.route == 'AH', 'without the status rule (Farm view): still an AH plan')
X("CEnvFl = Env({ vendor = { [602] = 10 }, vendorSell = function(id) return id == 600 and 400 or nil end })")
P = L("AF_NS.Farm.CraftPlan(AF_NS.Farm.Craft(600, CRec, CEnvFl), { share = 0.75, hours = 8, ahStatus = { good = true, slow = true } }, CEnvFl)")
ok(P and P.route == 'Vendor' and P.resell == 400, f"flooded but the vendor pays: a vendor-route plan ({P and P.route}, {P and P.crafts} crafts)")
X("Items[600].status = nil")

print(f'\n{fails} failed' if fails else '\nall passed')
sys.exit(1 if fails else 0)
